دالة ضرب_مصفوفتين(مصفوفة_أ، مصفوفة_ب) {
    متغير ن = طول(مصفوفة_أ)
    متغير مصفوفة_ج = [ [لاشيء] * ن ] * ن
    من_أجل (أ من ٠ إلى ن - ١) {
        من_أجل (ب من ٠ إلى ن - ١) {
            متغير مجموع = ٠
            من_أجل (ك من ٠ إلى ن - ١) {
                مجموع = مجموع + عدد(مصفوفة_أ[أ][ك]) * عدد(مصفوفة_ب[ك][ب])
            }
            مصفوفة_ج[أ][ب] = مجموع
        }
    }
    ارجع مصفوفة_ج
}
